@spec vm_grid_spec  src=tests/specs/vm_grid_spec.lua  loc=558  cases=23
@exercises trackerManager (h.tm), dataStore (h.ds), trackerView (h.vm), editCursor (h.ec), timing (timing), midiManager (h.fm)
@surface   tm:addEvent, tm:flush, ds:assign, tm:rebuild, vm:setGridSize, ec:selectChannel, ec:col, vm:rowBeatInfo, vm:addExtraCol, vm:noteLabel, vm:noteDeviation, timing.resolveFactors, timing.applyFactors, ec:setPos, vm:editEvent, fm:dump, timing.logPerRow
@harness   mk{seed.notes, seed.ccs, seed.resolution, seed.length}

# Intent
  Exercises vm's grid construction against seeded tm state.

# Helpers
  @fn chordStampRegion(h)  @ 15-21
  @fn colOn(h, chan, type, cc)  @ 28-32
  @fn noteColsOn(h, chan)  @ 34-40

# Cases
  @case 'one note on channel 1 surfaces as one note col with that event'  [harness]  @ 44-60
  @case 'notes on two channels expose both via channel selection'  [harness]  @ 64-81
  @case 'rowBeatInfo flags bar and beat boundaries under 4/4'  [harness]  @ 88-96
  @case 'cc columns appear sorted by cc number'  [harness]  @ 102-118
  @case 'kinds within a channel: pc → pb → note → at → cc'  [harness]  @ 122-140
  @case 'note grid columns carry their lane number'  [harness]  @ 145-161
  @case 'non-note columns have nil lane'  [harness]  @ 165-182
  @case 'grid.lane1Col indexes the lane-1 note column for each channel'  [harness]  @ 187-203
  @case 'addExtraCol on a channel with no notes preserves the implicit note column'  [harness]  @ 210-236
  @case 'empty take: 16 implicit lane-1 note cols, lane1Col covers all chans'  [harness]  @ 242-251
  @case 'note col without delay has the compact stop layout'  [harness]  @ 258-272
  @case 'note col with delay extends stops and widens'  [harness]  @ 276-290
  @case 'a note off its step widens its column by the readout'  [harness]  @ 297-309
  @case 'a note off the step it was written on reports its drift in the cell'  [harness]  @ 317-331
  @case 'extreme swing: a note authored under the current swing lands on its row, no off-grid flag'  [harness]  @ 340-367
  @case 'Phase 6: ppqL-stamped notes stay on-grid through a swing change'  [harness]  @ 376-403
  @case 'fresh PB authored under swing lands on-grid (no off-grid flag, regardless of period position)'  [harness]  @ 409-437
  @case 'fresh PB carries ppqL + frame after authoring'  [harness]  @ 443-472
  @case 'fractional ppqPerRow: an on-grid onset a tick below its row boundary snaps up, not down'  [harness]  @ 478-496
  @case 'a chain\'s derived lanes claim no note columns'  [harness]  @ 502-512
  @case 'authoring the lanes is what gives the derived voices columns'  [harness]  @ 516-526
  @case 'a pb chain claims no pb column'  [harness]  @ 530-541
  @case 'a cc chain claims no cc column, and the authored ones stand'  [harness]  @ 545-556

